    content: '' !important;
    position: absolute !important; top: -20px !important; right: -46px !important;
    width: 36px !important; height: 36px !important;
    border-radius: 50% !important;
    background: url('https://i.postimg.cc/63c7hYyF/IMG-4652.jpg') center/cover !important;
